window.JUZ_AMMA = [{"n": 78, "ar": "النبإ", "en": "An-Naba", "meaning": "The Tidings", "ayat": [{"a": "عَمَّ يَتَسَآءَلُونَ", "e": "About what are they asking one another"}, {"a": "عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ", "e": "About the great news"}, {"a": "ٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ", "e": "That over which they are in disagreement"}, {"a": "كَلَّا سَيَعۡلَمُونَ", "e": "No! They are going to know"}, {"a": "ثُمَّ كَلَّا سَيَعۡلَمُونَ", "e": "Then, no! They are going to know"}, {"a": "أَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا", "e": "Have We not made the earth a resting place"}, {"a": "وَٱلۡجِبَالَ أَوۡتَادٗا", "e": "And the mountains as stakes"}, {"a": "وَخَلَقۡنَٰكُمۡ أَزۡوَٰجٗا", "e": "And We created you in pairs"}, {"a": "وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا", "e": "And made your sleep [a means for] rest"}, {"a": "وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا", "e": "And made the night as clothing"}, {"a": "وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا", "e": "And made the day for livelihood"}, {"a": "وَبَنَيۡنَا فَوۡقَكُمۡ سَبۡعٗا شِدَادٗا", "e": "And constructed above you seven strong [heavens]"}, {"a": "وَجَعَلۡنَا سِرَاجٗا وَهَّاجٗا", "e": "And made [therein] a burning lamp"}, {"a": "وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا", "e": "And sent down, from the rain clouds, pouring water"}, {"a": "لِّنُخۡرِجَ بِهِۦ حَبّٗا وَنَبَاتٗا", "e": "That We may bring forth thereby grain and vegetation"}, {"a": "وَجَنَّـٰتٍ أَلۡفَافًا", "e": "And gardens of entwined growth"}, {"a": "إِنَّ يَوۡمَ ٱلۡفَصۡلِ كَانَ مِيقَٰتٗا", "e": "Indeed, the Day of Judgement is an appointed time"}, {"a": "يَوۡمَ يُنفَخُ فِي ٱلصُّورِ فَتَأۡتُونَ أَفۡوَاجٗا", "e": "The Day the Horn is blown and you will come forth in multitudes"}, {"a": "وَفُتِحَتِ ٱلسَّمَآءُ فَكَانَتۡ أَبۡوَٰبٗا", "e": "And the heaven is opened and will become gateways"}, {"a": "وَسُيِّرَتِ ٱلۡجِبَالُ فَكَانَتۡ سَرَابًا", "e": "And the mountains are removed and will be [but] a mirage"}, {"a": "إِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادٗا", "e": "Indeed, Hell has been lying in wait"}, {"a": "لِّلطَّـٰغِينَ مَـَٔابٗا", "e": "For the transgressors, a place of return"}, {"a": "لَّـٰبِثِينَ فِيهَآ أَحۡقَابٗا", "e": "In which they will remain for ages [unending]"}, {"a": "لَّا يَذُوقُونَ فِيهَا بَرۡدٗا وَلَا شَرَابًا", "e": "They will not taste therein [any] coolness or drink"}, {"a": "إِلَّا حَمِيمٗا وَغَسَّاقٗا", "e": "Except scalding water and [foul] purulence"}, {"a": "جَزَآءٗ وِفَاقًا", "e": "An appropriate recompense"}, {"a": "إِنَّهُمۡ كَانُواْ لَا يَرۡجُونَ حِسَابٗا", "e": "Indeed, they were not expecting an account"}, {"a": "وَكَذَّبُواْ بِـَٔايَٰتِنَا كِذَّابٗا", "e": "And denied Our verses with [emphatic] denial"}, {"a": "وَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ كِتَٰبٗا", "e": "But all things We have enumerated in writing"}, {"a": "فَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا", "e": "So taste [the penalty], and never will We increase you except in torment"}, {"a": "إِنَّ لِلۡمُتَّقِينَ مَفَازًا", "e": "Indeed, for the righteous is attainment"}, {"a": "حَدَآئِقَ وَأَعۡنَٰبٗا", "e": "Gardens and grapevines"}, {"a": "وَكَوَاعِبَ أَتۡرَابٗا", "e": "And full-breasted [companions] of equal age"}, {"a": "وَكَأۡسٗا دِهَاقٗا", "e": "And a full cup"}, {"a": "لَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّـٰبٗا", "e": "No ill speech will they hear therein or any falsehood"}, {"a": "جَزَآءٗ مِّن رَّبِّكَ عَطَآءً حِسَابٗا", "e": "[As] reward from your Lord, [a generous] gift [made due by] account"}, {"a": "رَّبِّ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَمَا بَيۡنَهُمَا ٱلرَّحۡمَٰنِۖ لَا يَمۡلِكُونَ مِنۡهُ خِطَابٗا", "e": "[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech"}, {"a": "يَوۡمَ يَقُومُ ٱلرُّوحُ وَٱلۡمَلَـٰٓئِكَةُ صَفّٗاۖ لَّا يَتَكَلَّمُونَ إِلَّا مَنۡ أَذِنَ لَهُ ٱلرَّحۡمَٰنُ وَقَالَ صَوَابٗا", "e": "The Day that the Spirit and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct"}, {"a": "ذَٰلِكَ ٱلۡيَوۡمُ ٱلۡحَقُّۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ مَـَٔابًا", "e": "That is the True Day; so he who wills may take to his Lord a [way of] return"}, {"a": "إِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا", "e": "Indeed, We have warned you of a near punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, \"Oh, I wish that I were dust"}]}, {"n": 79, "ar": "النازعات", "en": "An-Nazi'at", "meaning": "Those who drag forth", "ayat": [{"a": "وَٱلنَّـٰزِعَٰتِ غَرۡقٗا", "e": "By those [angels] who extract with violence"}, {"a": "وَٱلنَّـٰشِطَٰتِ نَشۡطٗا", "e": "And [by] those who remove with ease"}, {"a": "وَٱلسَّـٰبِحَٰتِ سَبۡحٗا", "e": "And [by] those who glide [as if] swimming"}, {"a": "فَٱلسَّـٰبِقَٰتِ سَبۡقٗا", "e": "And those who race each other in a race"}, {"a": "فَٱلۡمُدَبِّرَٰتِ أَمۡرٗا", "e": "And those who arrange [each] matter"}, {"a": "يَوۡمَ تَرۡجُفُ ٱلرَّاجِفَةُ", "e": "On the Day the blast [of the Horn] will convulse [creation]"}, {"a": "تَتۡبَعُهَا ٱلرَّادِفَةُ", "e": "There will follow it the subsequent [one]"}, {"a": "قُلُوبٞ يَوۡمَئِذٖ وَاجِفَةٌ", "e": "Hearts, that Day, will tremble"}, {"a": "أَبۡصَٰرُهَا خَٰشِعَةٞ", "e": "Their eyes humbled"}, {"a": "يَقُولُونَ أَءِنَّا لَمَرۡدُودُونَ فِي ٱلۡحَافِرَةِ", "e": "They are [presently] saying, \"Will we indeed be returned to [our] former state [of life]"}, {"a": "أَءِذَا كُنَّا عِظَٰمٗا نَّخِرَةٗ", "e": "Even if we should be decayed bones"}, {"a": "قَالُواْ تِلۡكَ إِذٗا كَرَّةٌ خَاسِرَةٞ", "e": "They say, \"That, then, would be a losing return"}, {"a": "فَإِنَّمَا هِيَ زَجۡرَةٞ وَٰحِدَةٞ", "e": "Indeed, it will be but one shout"}, {"a": "فَإِذَا هُم بِٱلسَّاهِرَةِ", "e": "And suddenly they will be [alert] upon the earth's surface"}, {"a": "هَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ", "e": "Has there reached you the story of Moses"}, {"a": "إِذۡ نَادَىٰهُ رَبُّهُۥ بِٱلۡوَادِ ٱلۡمُقَدَّسِ طُوًى", "e": "When his Lord called to him in the sacred valley of Tuwa"}, {"a": "ٱذۡهَبۡ إِلَىٰ فِرۡعَوۡنَ إِنَّهُۥ طَغَىٰ", "e": "Go to Pharaoh. Indeed, he has transgressed"}, {"a": "فَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ", "e": "And say to him, 'Would you [be willing to] purify yourself"}, {"a": "وَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ", "e": "And let me guide you to your Lord so you would fear [Him]"}, {"a": "فَأَرَىٰهُ ٱلۡأٓيَةَ ٱلۡكُبۡرَىٰ", "e": "And he showed him the greatest sign"}, {"a": "فَكَذَّبَ وَعَصَىٰ", "e": "But Pharaoh denied and disobeyed"}, {"a": "ثُمَّ أَدۡبَرَ يَسۡعَىٰ", "e": "Then he turned his back, striving"}, {"a": "فَحَشَرَ فَنَادَىٰ", "e": "And he gathered [his people] and called out"}, {"a": "فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ", "e": "And said, \"I am your most exalted lord"}, {"a": "فَأَخَذَهُ ٱللَّهُ نَكَالَ ٱلۡأٓخِرَةِ وَٱلۡأُولَىٰٓ", "e": "So Allah seized him in exemplary punishment for the last and the first [transgression]"}, {"a": "إِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّمَن يَخۡشَىٰٓ", "e": "Indeed in that is a warning for whoever would fear [Allah]"}, {"a": "ءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ بَنَىٰهَا", "e": "Are you a more difficult creation or is the heaven? Allah constructed it"}, {"a": "رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا", "e": "He raised its ceiling and proportioned it"}, {"a": "وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا", "e": "And He darkened its night and extracted its brightness"}, {"a": "وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ", "e": "And after that He spread the earth"}, {"a": "أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا", "e": "He extracted from it its water and its pasture"}, {"a": "وَٱلۡجِبَالَ أَرۡسَىٰهَا", "e": "And the mountains He set firmly"}, {"a": "مَتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ", "e": "As provision for you and your grazing livestock"}, {"a": "فَإِذَا جَآءَتِ ٱلطَّآمَّةُ ٱلۡكُبۡرَىٰ", "e": "But when there comes the greatest Overwhelming Calamity"}, {"a": "يَوۡمَ يَتَذَكَّرُ ٱلۡإِنسَٰنُ مَا سَعَىٰ", "e": "The Day when man will remember that for which he strove"}, {"a": "وَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ", "e": "And Hellfire will be exposed for [all] those who see"}, {"a": "فَأَمَّا مَن طَغَىٰ", "e": "So as for he who transgressed"}, {"a": "وَءَاثَرَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا", "e": "And preferred the life of the world"}, {"a": "فَإِنَّ ٱلۡجَحِيمَ هِيَ ٱلۡمَأۡوَىٰ", "e": "Then indeed, Hellfire will be [his] refuge"}, {"a": "وَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ", "e": "But as for he who feared the position of his Lord and prevented the soul from [unlawful] inclination"}, {"a": "فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ", "e": "Then indeed, Paradise will be [his] refuge"}, {"a": "يَسۡـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرۡسَىٰهَا", "e": "They ask you, [O Muhammad], about the Hour: when is its arrival"}, {"a": "فِيمَ أَنتَ مِن ذِكۡرَىٰهَآ", "e": "In what [position] are you that you should mention it"}, {"a": "إِلَىٰ رَبِّكَ مُنتَهَىٰهَآ", "e": "To your Lord is its finality"}, {"a": "إِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا", "e": "You are only a warner for those who fear it"}, {"a": "كَأَنَّهُمۡ يَوۡمَ يَرَوۡنَهَا لَمۡ يَلۡبَثُوٓاْ إِلَّا عَشِيَّةً أَوۡ ضُحَىٰهَا", "e": "It will be, on the Day they see it, as though they had not remained [in the world] except for an afternoon or a morning thereof"}]}, {"n": 80, "ar": "عبس", "en": "'Abasa", "meaning": "He Frowned", "ayat": [{"a": "عَبَسَ وَتَوَلَّىٰٓ", "e": "The Prophet frowned and turned away"}, {"a": "أَن جَآءَهُ ٱلۡأَعۡمَىٰ", "e": "Because there came to him the blind man, [interrupting]"}, {"a": "وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ", "e": "But what would make you perceive, [O Muhammad], that perhaps he might be purified"}, {"a": "أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ", "e": "Or be reminded and the remembrance would benefit him"}, {"a": "أَمَّا مَنِ ٱسۡتَغۡنَىٰ", "e": "As for he who thinks himself without need"}, {"a": "فَأَنتَ لَهُۥ تَصَدَّىٰ", "e": "To him you give attention"}, {"a": "وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ", "e": "And not upon you [is any blame] if he will not be purified"}, {"a": "وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ", "e": "But as for he who came to you striving [for knowledge]"}, {"a": "وَهُوَ يَخۡشَىٰ", "e": "While he fears [Allah]"}, {"a": "فَأَنتَ عَنۡهُ تَلَهَّىٰ", "e": "From him you are distracted"}, {"a": "كَلَّآ إِنَّهَا تَذۡكِرَةٞ", "e": "No! Indeed, these verses are a reminder"}, {"a": "فَمَن شَآءَ ذَكَرَهُۥ", "e": "So whoever wills may remember it"}, {"a": "فِي صُحُفٖ مُّكَرَّمَةٖ", "e": "[It is recorded] in honored sheets"}, {"a": "مَّرۡفُوعَةٖ مُّطَهَّرَةِۭ", "e": "Exalted and purified"}, {"a": "بِأَيۡدِي سَفَرَةٖ", "e": "[Carried] by the hands of messenger-angels"}, {"a": "كِرَامِۭ بَرَرَةٖ", "e": "Noble and dutiful"}, {"a": "قُتِلَ ٱلۡإِنسَٰنُ مَآ أَكۡفَرَهُۥ", "e": "Cursed is man; how disbelieving is he"}, {"a": "مِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ", "e": "From what substance did He create him"}, {"a": "مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ", "e": "From a sperm-drop He created him and destined for him"}, {"a": "ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ", "e": "Then He eased the way for him"}, {"a": "ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ", "e": "Then He causes his death and provides a grave for him"}, {"a": "ثُمَّ إِذَا شَآءَ أَنشَرَهُۥ", "e": "Then when He wills, He will resurrect him"}, {"a": "كَلَّا لَمَّا يَقۡضِ مَآ أَمَرَهُۥ", "e": "No! Man has not yet accomplished what He commanded him"}, {"a": "فَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ", "e": "Then let mankind look at his food"}, {"a": "أَنَّا صَبَبۡنَا ٱلۡمَآءَ صَبّٗا", "e": "How We poured down water in torrents"}, {"a": "ثُمَّ شَقَقۡنَا ٱلۡأَرۡضَ شَقّٗا", "e": "Then We broke open the earth, splitting [it with sprouts]"}, {"a": "فَأَنۢبَتۡنَا فِيهَا حَبّٗا", "e": "And caused to grow within it grain"}, {"a": "وَعِنَبٗا وَقَضۡبٗا", "e": "And grapes and herbage"}, {"a": "وَزَيۡتُونٗا وَنَخۡلٗا", "e": "And olive and palm trees"}, {"a": "وَحَدَآئِقَ غُلۡبٗا", "e": "And gardens of dense shrubbery"}, {"a": "وَفَٰكِهَةٗ وَأَبّٗا", "e": "And fruit and grass"}, {"a": "مَّتَٰعٗا لَّكُمۡ وَلِأَنۡعَٰمِكُمۡ", "e": "[As] enjoyment for you and your grazing livestock"}, {"a": "فَإِذَا جَآءَتِ ٱلصَّآخَّةُ", "e": "But when there comes the Deafening Blast"}, {"a": "يَوۡمَ يَفِرُّ ٱلۡمَرۡءُ مِنۡ أَخِيهِ", "e": "On the Day a man will flee from his brother"}, {"a": "وَأُمِّهِۦ وَأَبِيهِ", "e": "And his mother and his father"}, {"a": "وَصَٰحِبَتِهِۦ وَبَنِيهِ", "e": "And his wife and his children"}, {"a": "لِكُلِّ ٱمۡرِيٕٖ مِّنۡهُمۡ يَوۡمَئِذٖ شَأۡنٞ يُغۡنِيهِ", "e": "For every man, that Day, will be a matter adequate for him"}, {"a": "وُجُوهٞ يَوۡمَئِذٖ مُّسۡفِرَةٞ", "e": "[Some] faces, that Day, will be bright"}, {"a": "ضَاحِكَةٞ مُّسۡتَبۡشِرَةٞ", "e": "Laughing, rejoicing at good news"}, {"a": "وَوُجُوهٞ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٞ", "e": "And [other] faces, that Day, will have upon them dust"}, {"a": "تَرۡهَقُهَا قَتَرَةٌ", "e": "Blackness will cover them"}, {"a": "أُوْلَـٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ", "e": "Those are the disbelievers, the wicked ones"}]}, {"n": 81, "ar": "التكوير", "en": "At-Takwir", "meaning": "The Overthrowing", "ayat": [{"a": "إِذَا ٱلشَّمۡسُ كُوِّرَتۡ", "e": "When the sun is wrapped up [in darkness]"}, {"a": "وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ", "e": "And when the stars fall, dispersing"}, {"a": "وَإِذَا ٱلۡجِبَالُ سُيِّرَتۡ", "e": "And when the mountains are removed"}, {"a": "وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ", "e": "And when full-term she-camels are neglected"}, {"a": "وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ", "e": "And when the wild beasts are gathered"}, {"a": "وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ", "e": "And when the seas are filled with flame"}, {"a": "وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ", "e": "And when the souls are paired"}, {"a": "وَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ", "e": "And when the girl [who was] buried alive is asked"}, {"a": "بِأَيِّ ذَنۢبٖ قُتِلَتۡ", "e": "For what sin she was killed"}, {"a": "وَإِذَا ٱلصُّحُفُ نُشِرَتۡ", "e": "And when the pages are made public"}, {"a": "وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ", "e": "And when the sky is stripped away"}, {"a": "وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ", "e": "And when Hellfire is set ablaze"}, {"a": "وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ", "e": "And when Paradise is brought near"}, {"a": "عَلِمَتۡ نَفۡسٞ مَّآ أَحۡضَرَتۡ", "e": "A soul will [then] know what it has brought [with it]"}, {"a": "فَلَآ أُقۡسِمُ بِٱلۡخُنَّسِ", "e": "So I swear by the retreating stars"}, {"a": "ٱلۡجَوَارِ ٱلۡكُنَّسِ", "e": "Those that run [their courses] and disappear"}, {"a": "وَٱلَّيۡلِ إِذَا عَسۡعَسَ", "e": "And by the night as it closes in"}, {"a": "وَٱلصُّبۡحِ إِذَا تَنَفَّسَ", "e": "And by the dawn when it breathes"}, {"a": "إِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ", "e": "[That] indeed, the Qur'an is a word [conveyed by] a noble messenger"}, {"a": "ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينٖ", "e": "[Who is] possessed of power and with the Owner of the Throne, secure [in position]"}, {"a": "مُّطَاعٖ ثَمَّ أَمِينٖ", "e": "Obeyed there [in the heavens] and trustworthy"}, {"a": "وَمَا صَاحِبُكُم بِمَجۡنُونٖ", "e": "And your companion is not [at all] mad"}, {"a": "وَلَقَدۡ رَءَاهُ بِٱلۡأُفُقِ ٱلۡمُبِينِ", "e": "And he has already seen Gabriel in the clear horizon"}, {"a": "وَمَا هُوَ عَلَى ٱلۡغَيۡبِ بِضَنِينٖ", "e": "And Muhammad is not a withholder of [knowledge of] the unseen"}, {"a": "وَمَا هُوَ بِقَوۡلِ شَيۡطَٰنٖ رَّجِيمٖ", "e": "And the Qur'an is not the word of a devil, expelled [from the heavens]"}, {"a": "فَأَيۡنَ تَذۡهَبُونَ", "e": "So where are you going"}, {"a": "إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ", "e": "It is not except a reminder to the worlds"}, {"a": "لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ", "e": "For whoever wills among you to take a right course"}, {"a": "وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ", "e": "And you do not will except that Allah wills - Lord of the worlds"}]}, {"n": 82, "ar": "الإنفطار", "en": "Al-Infitar", "meaning": "The Cleaving", "ayat": [{"a": "إِذَا ٱلسَّمَآءُ ٱنفَطَرَتۡ", "e": "When the sky breaks apart"}, {"a": "وَإِذَا ٱلۡكَوَاكِبُ ٱنتَثَرَتۡ", "e": "And when the stars fall, scattering"}, {"a": "وَإِذَا ٱلۡبِحَارُ فُجِّرَتۡ", "e": "And when the seas are erupted"}, {"a": "وَإِذَا ٱلۡقُبُورُ بُعۡثِرَتۡ", "e": "And when the [contents of] graves are scattered"}, {"a": "عَلِمَتۡ نَفۡسٞ مَّا قَدَّمَتۡ وَأَخَّرَتۡ", "e": "A soul will [then] know what it has put forth and kept back"}, {"a": "يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ", "e": "O mankind, what has deceived you concerning your Lord, the Generous"}, {"a": "ٱلَّذِي خَلَقَكَ فَسَوَّىٰكَ فَعَدَلَكَ", "e": "Who created you, proportioned you, and balanced you"}, {"a": "فِيٓ أَيِّ صُورَةٖ مَّا شَآءَ رَكَّبَكَ", "e": "In whatever form He willed has He assembled you"}, {"a": "كَلَّا بَلۡ تُكَذِّبُونَ بِٱلدِّينِ", "e": "No! But you deny the Recompense"}, {"a": "وَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ", "e": "And indeed, [appointed] over you are keepers"}, {"a": "كِرَامٗا كَٰتِبِينَ", "e": "Noble and recording"}, {"a": "يَعۡلَمُونَ مَا تَفۡعَلُونَ", "e": "They know whatever you do"}, {"a": "إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ", "e": "Indeed, the righteous will be in pleasure"}, {"a": "وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ", "e": "And indeed, the wicked will be in Hellfire"}, {"a": "يَصۡلَوۡنَهَا يَوۡمَ ٱلدِّينِ", "e": "They will [enter to] burn therein on the Day of Recompense"}, {"a": "وَمَا هُمۡ عَنۡهَا بِغَآئِبِينَ", "e": "And never therefrom will they be absent"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ", "e": "And what can make you know what is the Day of Recompense"}, {"a": "ثُمَّ مَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلدِّينِ", "e": "Then, what can make you know what is the Day of Recompense"}, {"a": "يَوۡمَ لَا تَمۡلِكُ نَفۡسٞ لِّنَفۡسٖ شَيۡـٔٗاۖ وَٱلۡأَمۡرُ يَوۡمَئِذٖ لِّلَّهِ", "e": "It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah"}]}, {"n": 83, "ar": "المطففين", "en": "Al-Mutaffifin", "meaning": "The Defrauding", "ayat": [{"a": "وَيۡلٞ لِّلۡمُطَفِّفِينَ", "e": "Woe to those who give less [than due]"}, {"a": "ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ", "e": "Who, when they take a measure from people, take in full"}, {"a": "وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ", "e": "But if they give by measure or by weight to them, they cause loss"}, {"a": "أَلَا يَظُنُّ أُوْلَـٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ", "e": "Do they not think that they will be resurrected"}, {"a": "لِيَوۡمٍ عَظِيمٖ", "e": "For a tremendous Day"}, {"a": "يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ", "e": "The Day when mankind will stand before the Lord of the worlds"}, {"a": "كَلَّآ إِنَّ كِتَٰبَ ٱلۡفُجَّارِ لَفِي سِجِّينٖ", "e": "No! Indeed, the record of the wicked is in sijjeen"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا سِجِّينٞ", "e": "And what can make you know what is sijjeen"}, {"a": "كِتَٰبٞ مَّرۡقُومٞ", "e": "It is [their destination recorded in] a register inscribed"}, {"a": "وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ", "e": "Woe, that Day, to the deniers"}, {"a": "ٱلَّذِينَ يُكَذِّبُونَ بِيَوۡمِ ٱلدِّينِ", "e": "Who deny the Day of Recompense"}, {"a": "وَمَا يُكَذِّبُ بِهِۦٓ إِلَّا كُلُّ مُعۡتَدٍ أَثِيمٍ", "e": "And none deny it except every sinful transgressor"}, {"a": "إِذَا تُتۡلَىٰ عَلَيۡهِ ءَايَٰتُنَا قَالَ أَسَٰطِيرُ ٱلۡأَوَّلِينَ", "e": "When Our verses are recited to him, he says, \"Legends of the former peoples"}, {"a": "كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ", "e": "No! Rather, the stain has covered their hearts of that which they were earning"}, {"a": "كَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ", "e": "No! Indeed, from their Lord, that Day, they will be partitioned"}, {"a": "ثُمَّ إِنَّهُمۡ لَصَالُواْ ٱلۡجَحِيمِ", "e": "Then indeed, they will [enter and] burn in Hellfire"}, {"a": "ثُمَّ يُقَالُ هَٰذَا ٱلَّذِي كُنتُم بِهِۦ تُكَذِّبُونَ", "e": "Then it will be said [to them], \"This is what you used to deny"}, {"a": "كَلَّآ إِنَّ كِتَٰبَ ٱلۡأَبۡرَارِ لَفِي عِلِّيِّينَ", "e": "No! Indeed, the record of the righteous is in 'illiyyun"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا عِلِّيُّونَ", "e": "And what can make you know what is 'illiyyun"}, {"a": "كِتَٰبٞ مَّرۡقُومٞ", "e": "It is [their destination recorded in] a register inscribed"}, {"a": "يَشۡهَدُهُ ٱلۡمُقَرَّبُونَ", "e": "Which is witnessed by those brought near [to Allah]"}, {"a": "إِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٍ", "e": "Indeed, the righteous will be in pleasure"}, {"a": "عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ", "e": "On adorned couches, observing"}, {"a": "تَعۡرِفُ فِي وُجُوهِهِمۡ نَضۡرَةَ ٱلنَّعِيمِ", "e": "You will recognize in their faces the radiance of pleasure"}, {"a": "يُسۡقَوۡنَ مِن رَّحِيقٖ مَّخۡتُومٍ", "e": "They will be given to drink [pure] wine [which was] sealed"}, {"a": "خِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ", "e": "The last of it is musk. So for this let the competitors compete"}, {"a": "وَمِزَاجُهُۥ مِن تَسۡنِيمٍ", "e": "And its mixture is of Tasneem"}, {"a": "عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ", "e": "A spring from which those near [to Allah] drink"}, {"a": "إِنَّ ٱلَّذِينَ أَجۡرَمُواْ كَانُواْ مِنَ ٱلَّذِينَ ءَامَنُواْ يَضۡحَكُونَ", "e": "Indeed, those who committed crimes used to laugh at those who believed"}, {"a": "وَإِذَا مَرُّواْ بِهِمۡ يَتَغَامَزُونَ", "e": "And when they passed by them, they would exchange derisive glances"}, {"a": "وَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ", "e": "And when they returned to their people, they would return jesting"}, {"a": "وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ", "e": "And when they saw them, they would say, \"Indeed, those are truly lost"}, {"a": "وَمَآ أُرۡسِلُواْ عَلَيۡهِمۡ حَٰفِظِينَ", "e": "But they had not been sent as guardians over them"}, {"a": "فَٱلۡيَوۡمَ ٱلَّذِينَ ءَامَنُواْ مِنَ ٱلۡكُفَّارِ يَضۡحَكُونَ", "e": "So Today those who believed are laughing at the disbelievers"}, {"a": "عَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ", "e": "On adorned couches, observing"}, {"a": "هَلۡ ثُوِّبَ ٱلۡكُفَّارُ مَا كَانُواْ يَفۡعَلُونَ", "e": "Have the disbelievers [not] been rewarded [this Day] for what they used to do"}]}, {"n": 84, "ar": "الإنشقاق", "en": "Al-Inshiqaq", "meaning": "The Sundering", "ayat": [{"a": "إِذَا ٱلسَّمَآءُ ٱنشَقَّتۡ", "e": "When the sky has split [open]"}, {"a": "وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ", "e": "And has responded to its Lord and was obligated [to do so]"}, {"a": "وَإِذَا ٱلۡأَرۡضُ مُدَّتۡ", "e": "And when the earth has been extended"}, {"a": "وَأَلۡقَتۡ مَا فِيهَا وَتَخَلَّتۡ", "e": "And has cast out that within it and relinquished [it]"}, {"a": "وَأَذِنَتۡ لِرَبِّهَا وَحُقَّتۡ", "e": "And has responded to its Lord and was obligated [to do so]"}, {"a": "يَـٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحٗا فَمُلَٰقِيهِ", "e": "O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it"}, {"a": "فَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ بِيَمِينِهِۦ", "e": "Then as for he who is given his record in his right hand"}, {"a": "فَسَوۡفَ يُحَاسَبُ حِسَابٗا يَسِيرٗا", "e": "He will be judged with an easy account"}, {"a": "وَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورٗا", "e": "And return to his people in happiness"}, {"a": "وَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ", "e": "But as for he who is given his record behind his back"}, {"a": "فَسَوۡفَ يَدۡعُواْ ثُبُورٗا", "e": "He will cry out for destruction"}, {"a": "وَيَصۡلَىٰ سَعِيرًا", "e": "And [enter to] burn in a Blaze"}, {"a": "إِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا", "e": "Indeed, he had [once] been among his people in happiness"}, {"a": "إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ", "e": "Indeed, he had thought he would never return [to Allah]"}, {"a": "بَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرٗا", "e": "But yes! Indeed, his Lord was ever of him, Seeing"}, {"a": "فَلَآ أُقۡسِمُ بِٱلشَّفَقِ", "e": "So I swear by the twilight glow"}, {"a": "وَٱلَّيۡلِ وَمَا وَسَقَ", "e": "And [by] the night and what it envelops"}, {"a": "وَٱلۡقَمَرِ إِذَا ٱتَّسَقَ", "e": "And [by] the moon when it becomes full"}, {"a": "لَتَرۡكَبُنَّ طَبَقًا عَن طَبَقٖ", "e": "[That] you will surely experience state after state"}, {"a": "فَمَا لَهُمۡ لَا يُؤۡمِنُونَ", "e": "So what is [the matter] with them [that] they do not believe"}, {"a": "وَإِذَا قُرِئَ عَلَيۡهِمُ ٱلۡقُرۡءَانُ لَا يَسۡجُدُونَۤ۩", "e": "And when the Qur'an is recited to them, they do not prostrate [to Allah]"}, {"a": "بَلِ ٱلَّذِينَ كَفَرُواْ يُكَذِّبُونَ", "e": "But those who have disbelieved deny"}, {"a": "وَٱللَّهُ أَعۡلَمُ بِمَا يُوعُونَ", "e": "And Allah is most knowing of what they keep within themselves"}, {"a": "فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ", "e": "So give them tidings of a painful punishment"}, {"a": "إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونِۭ", "e": "Except for those who believe and do righteous deeds. For them is a reward uninterrupted"}]}, {"n": 85, "ar": "البروج", "en": "Al-Buruj", "meaning": "The Mansions of the Stars", "ayat": [{"a": "وَٱلسَّمَآءِ ذَاتِ ٱلۡبُرُوجِ", "e": "By the sky containing great stars"}, {"a": "وَٱلۡيَوۡمِ ٱلۡمَوۡعُودِ", "e": "And [by] the promised Day"}, {"a": "وَشَاهِدٖ وَمَشۡهُودٖ", "e": "And [by] the witness and what is witnessed"}, {"a": "قُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ", "e": "Cursed were the companions of the trench"}, {"a": "ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ", "e": "[Containing] the fire full of fuel"}, {"a": "إِذۡ هُمۡ عَلَيۡهَا قُعُودٞ", "e": "When they were sitting near it"}, {"a": "وَهُمۡ عَلَىٰ مَا يَفۡعَلُونَ بِٱلۡمُؤۡمِنِينَ شُهُودٞ", "e": "And they, to what they were doing against the believers, were witnesses"}, {"a": "وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ", "e": "And they resented them not except because they believed in Allah, the Exalted in Might, the Praiseworthy"}, {"a": "ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ", "e": "To whom belongs the dominion of the heavens and the earth. And Allah, over all things, is Witness"}, {"a": "إِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ", "e": "Indeed, those who have tortured the believing men and believing women and then have not repented will have the punishment of Hell, and they will have the punishment of the Burning Fire"}, {"a": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَهُمۡ جَنَّـٰتٞ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۚ ذَٰلِكَ ٱلۡفَوۡزُ ٱلۡكَبِيرُ", "e": "Indeed, those who have believed and done righteous deeds will have gardens beneath which rivers flow. That is the great attainment"}, {"a": "إِنَّ بَطۡشَ رَبِّكَ لَشَدِيدٌ", "e": "Indeed, the vengeance of your Lord is severe"}, {"a": "إِنَّهُۥ هُوَ يُبۡدِئُ وَيُعِيدُ", "e": "Indeed, it is He who originates [creation] and repeats"}, {"a": "وَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ", "e": "And He is the Forgiving, the Affectionate"}, {"a": "ذُو ٱلۡعَرۡشِ ٱلۡمَجِيدُ", "e": "Honorable Owner of the Throne"}, {"a": "فَعَّالٞ لِّمَا يُرِيدُ", "e": "Effecter of what He intends"}, {"a": "هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ", "e": "Has there reached you the story of the soldiers"}, {"a": "فِرۡعَوۡنَ وَثَمُودَ", "e": "[Those of] Pharaoh and Thamud"}, {"a": "بَلِ ٱلَّذِينَ كَفَرُواْ فِي تَكۡذِيبٖ", "e": "But they who disbelieve are in [persistent] denial"}, {"a": "وَٱللَّهُ مِن وَرَآئِهِم مُّحِيطُۢ", "e": "While Allah encompasses them from behind"}, {"a": "بَلۡ هُوَ قُرۡءَانٞ مَّجِيدٞ", "e": "But this is an honored Qur'an"}, {"a": "فِي لَوۡحٖ مَّحۡفُوظِۭ", "e": "[Inscribed] in a Preserved Slate"}]}, {"n": 86, "ar": "الطارق", "en": "At-Tariq", "meaning": "The Nightcommer", "ayat": [{"a": "وَٱلسَّمَآءِ وَٱلطَّارِقِ", "e": "By the sky and the night comer"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا ٱلطَّارِقُ", "e": "And what can make you know what is the night comer"}, {"a": "ٱلنَّجۡمُ ٱلثَّاقِبُ", "e": "It is the piercing star"}, {"a": "إِن كُلُّ نَفۡسٖ لَّمَّا عَلَيۡهَا حَافِظٞ", "e": "There is no soul but that it has over it a protector"}, {"a": "فَلۡيَنظُرِ ٱلۡإِنسَٰنُ مِمَّ خُلِقَ", "e": "So let man observe from what he was created"}, {"a": "خُلِقَ مِن مَّآءٖ دَافِقٖ", "e": "He was created from a fluid, ejected"}, {"a": "يَخۡرُجُ مِنۢ بَيۡنِ ٱلصُّلۡبِ وَٱلتَّرَآئِبِ", "e": "Emerging from between the backbone and the ribs"}, {"a": "إِنَّهُۥ عَلَىٰ رَجۡعِهِۦ لَقَادِرٞ", "e": "Indeed, Allah, to return him [to life], is Able"}, {"a": "يَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ", "e": "The Day when secrets will be put on trial"}, {"a": "فَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖ", "e": "Then man will have no power or any helper"}, {"a": "وَٱلسَّمَآءِ ذَاتِ ٱلرَّجۡعِ", "e": "By the sky which returns [rain]"}, {"a": "وَٱلۡأَرۡضِ ذَاتِ ٱلصَّدۡعِ", "e": "And [by] the earth which cracks open"}, {"a": "إِنَّهُۥ لَقَوۡلٞ فَصۡلٞ", "e": "Indeed, the Qur'an is a decisive statement"}, {"a": "وَمَا هُوَ بِٱلۡهَزۡلِ", "e": "And it is not amusement"}, {"a": "إِنَّهُمۡ يَكِيدُونَ كَيۡدٗا", "e": "Indeed, they are planning a plan"}, {"a": "وَأَكِيدُ كَيۡدٗا", "e": "But I am planning a plan"}, {"a": "فَمَهِّلِ ٱلۡكَٰفِرِينَ أَمۡهِلۡهُمۡ رُوَيۡدَۢا", "e": "So allow time for the disbelievers. Leave them awhile"}]}, {"n": 87, "ar": "الأعلى", "en": "Al-A'la", "meaning": "The Most High", "ayat": [{"a": "سَبِّحِ ٱسۡمَ رَبِّكَ ٱلۡأَعۡلَى", "e": "Exalt the name of your Lord, the Most High"}, {"a": "ٱلَّذِي خَلَقَ فَسَوَّىٰ", "e": "Who created and proportioned"}, {"a": "وَٱلَّذِي قَدَّرَ فَهَدَىٰ", "e": "And who destined and [then] guided"}, {"a": "وَٱلَّذِيٓ أَخۡرَجَ ٱلۡمَرۡعَىٰ", "e": "And who brings out the pasture"}, {"a": "فَجَعَلَهُۥ غُثَآءً أَحۡوَىٰ", "e": "And [then] makes it black stubble"}, {"a": "سَنُقۡرِئُكَ فَلَا تَنسَىٰٓ", "e": "We will make you recite, [O Muhammad], and you will not forget"}, {"a": "إِلَّا مَا شَآءَ ٱللَّهُۚ إِنَّهُۥ يَعۡلَمُ ٱلۡجَهۡرَ وَمَا يَخۡفَىٰ", "e": "Except what Allah should will. Indeed, He knows what is declared and what is hidden"}, {"a": "وَنُيَسِّرُكَ لِلۡيُسۡرَىٰ", "e": "And We will ease you toward ease"}, {"a": "فَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ", "e": "So remind, if the reminder should benefit"}, {"a": "سَيَذَّكَّرُ مَن يَخۡشَىٰ", "e": "He who fears [Allah] will be reminded"}, {"a": "وَيَتَجَنَّبُهَا ٱلۡأَشۡقَى", "e": "But the wretched one will avoid it"}, {"a": "ٱلَّذِي يَصۡلَى ٱلنَّارَ ٱلۡكُبۡرَىٰ", "e": "[He] who will [enter and] burn in the greatest Fire"}, {"a": "ثُمَّ لَا يَمُوتُ فِيهَا وَلَا يَحۡيَىٰ", "e": "Neither dying therein nor living"}, {"a": "قَدۡ أَفۡلَحَ مَن تَزَكَّىٰ", "e": "He has certainly succeeded who purifies himself"}, {"a": "وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ", "e": "And mentions the name of his Lord and prays"}, {"a": "بَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا", "e": "But you prefer the worldly life"}, {"a": "وَٱلۡأٓخِرَةُ خَيۡرٞ وَأَبۡقَىٰٓ", "e": "While the Hereafter is better and more enduring"}, {"a": "إِنَّ هَٰذَا لَفِي ٱلصُّحُفِ ٱلۡأُولَىٰ", "e": "Indeed, this is in the former scriptures"}, {"a": "صُحُفِ إِبۡرَٰهِيمَ وَمُوسَىٰ", "e": "The scriptures of Abraham and Moses"}]}, {"n": 88, "ar": "الغاشية", "en": "Al-Ghashiyah", "meaning": "The Overwhelming", "ayat": [{"a": "هَلۡ أَتَىٰكَ حَدِيثُ ٱلۡغَٰشِيَةِ", "e": "Has there reached you the report of the Overwhelming [event]"}, {"a": "وُجُوهٞ يَوۡمَئِذٍ خَٰشِعَةٌ", "e": "[Some] faces, that Day, will be humbled"}, {"a": "عَامِلَةٞ نَّاصِبَةٞ", "e": "Working [hard] and exhausted"}, {"a": "تَصۡلَىٰ نَارًا حَامِيَةٗ", "e": "They will [enter to] burn in an intensely hot Fire"}, {"a": "تُسۡقَىٰ مِنۡ عَيۡنٍ ءَانِيَةٖ", "e": "They will be given drink from a boiling spring"}, {"a": "لَّيۡسَ لَهُمۡ طَعَامٌ إِلَّا مِن ضَرِيعٖ", "e": "For them there will be no food except from a poisonous, thorny plant"}, {"a": "لَّا يُسۡمِنُ وَلَا يُغۡنِي مِن جُوعٖ", "e": "Which neither nourishes nor avails against hunger"}, {"a": "وُجُوهٞ يَوۡمَئِذٖ نَّاعِمَةٞ", "e": "[Other] faces, that Day, will show pleasure"}, {"a": "لِّسَعۡيِهَا رَاضِيَةٞ", "e": "With their effort [they are] satisfied"}, {"a": "فِي جَنَّةٍ عَالِيَةٖ", "e": "In an elevated garden"}, {"a": "لَّا تَسۡمَعُ فِيهَا لَٰغِيَةٗ", "e": "Wherein they will hear no unsuitable speech"}, {"a": "فِيهَا عَيۡنٞ جَارِيَةٞ", "e": "Within it is a flowing spring"}, {"a": "فِيهَا سُرُرٞ مَّرۡفُوعَةٞ", "e": "Within it are couches raised high"}, {"a": "وَأَكۡوَابٞ مَّوۡضُوعَةٞ", "e": "And cups put in place"}, {"a": "وَنَمَارِقُ مَصۡفُوفَةٞ", "e": "And cushions lined up"}, {"a": "وَزَرَابِيُّ مَبۡثُوثَةٌ", "e": "And carpets spread around"}, {"a": "أَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ", "e": "Then do they not look at the camels - how they are created"}, {"a": "وَإِلَى ٱلسَّمَآءِ كَيۡفَ رُفِعَتۡ", "e": "And at the sky - how it is raised"}, {"a": "وَإِلَى ٱلۡجِبَالِ كَيۡفَ نُصِبَتۡ", "e": "And at the mountains - how they are erected"}, {"a": "وَإِلَى ٱلۡأَرۡضِ كَيۡفَ سُطِحَتۡ", "e": "And at the earth - how it is spread out"}, {"a": "فَذَكِّرۡ إِنَّمَآ أَنتَ مُذَكِّرٞ", "e": "So remind, [O Muhammad]; you are only a reminder"}, {"a": "لَّسۡتَ عَلَيۡهِم بِمُصَيۡطِرٍ", "e": "You are not over them a controller"}, {"a": "إِلَّا مَن تَوَلَّىٰ وَكَفَرَ", "e": "However, he who turns away and disbelieves"}, {"a": "فَيُعَذِّبُهُ ٱللَّهُ ٱلۡعَذَابَ ٱلۡأَكۡبَرَ", "e": "Then Allah will punish him with the greatest punishment"}, {"a": "إِنَّ إِلَيۡنَآ إِيَابَهُمۡ", "e": "Indeed, to Us is their return"}, {"a": "ثُمَّ إِنَّ عَلَيۡنَا حِسَابَهُم", "e": "Then indeed, upon Us is their account"}]}, {"n": 89, "ar": "الفجر", "en": "Al-Fajr", "meaning": "The Dawn", "ayat": [{"a": "وَٱلۡفَجۡرِ", "e": "By the dawn"}, {"a": "وَلَيَالٍ عَشۡرٖ", "e": "And [by] ten nights"}, {"a": "وَٱلشَّفۡعِ وَٱلۡوَتۡرِ", "e": "And [by] the even [number] and the odd"}, {"a": "وَٱلَّيۡلِ إِذَا يَسۡرِ", "e": "And [by] the night when it passes"}, {"a": "هَلۡ فِي ذَٰلِكَ قَسَمٞ لِّذِي حِجۡرٍ", "e": "Is there [not] in [all] that an oath [sufficient] for one of perception"}, {"a": "أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِعَادٍ", "e": "Have you not considered how your Lord dealt with 'Aad"}, {"a": "إِرَمَ ذَاتِ ٱلۡعِمَادِ", "e": "[With] Iram - who had lofty pillars"}, {"a": "ٱلَّتِي لَمۡ يُخۡلَقۡ مِثۡلُهَا فِي ٱلۡبِلَٰدِ", "e": "The likes of whom had never been created in the land"}, {"a": "وَثَمُودَ ٱلَّذِينَ جَابُواْ ٱلصَّخۡرَ بِٱلۡوَادِ", "e": "And [with] Thamud, who carved out the rocks in the valley"}, {"a": "وَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ", "e": "And [with] Pharaoh, owner of the stakes"}, {"a": "ٱلَّذِينَ طَغَوۡاْ فِي ٱلۡبِلَٰدِ", "e": "[All of] whom oppressed within the lands"}, {"a": "فَأَكۡثَرُواْ فِيهَا ٱلۡفَسَادَ", "e": "And increased therein the corruption"}, {"a": "فَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ", "e": "So your Lord poured upon them a scourge of punishment"}, {"a": "إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ", "e": "Indeed, your Lord is in observation"}, {"a": "فَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ", "e": "And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, \"My Lord has honored me"}, {"a": "وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ", "e": "But when He tries him and restricts his provision, he says, \"My Lord has humiliated me"}, {"a": "كَلَّاۖ بَل لَّا تُكۡرِمُونَ ٱلۡيَتِيمَ", "e": "No! But you do not honor the orphan"}, {"a": "وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ", "e": "And you do not encourage one another to feed the poor"}, {"a": "وَتَأۡكُلُونَ ٱلتُّرَاثَ أَكۡلٗا لَّمّٗا", "e": "And you consume inheritance, devouring [it] altogether"}, {"a": "وَتُحِبُّونَ ٱلۡمَالَ حُبّٗا جَمّٗا", "e": "And you love wealth with immense love"}, {"a": "كَلَّآۖ إِذَا دُكَّتِ ٱلۡأَرۡضُ دَكّٗا دَكّٗا", "e": "No! When the earth has been leveled - pounded and crushed"}, {"a": "وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا", "e": "And your Lord has come and the angels, rank upon rank"}, {"a": "وَجِاْيٓءَ يَوۡمَئِذِۭ بِجَهَنَّمَۚ يَوۡمَئِذٖ يَتَذَكَّرُ ٱلۡإِنسَٰنُ وَأَنَّىٰ لَهُ ٱلذِّكۡرَىٰ", "e": "And brought [within view], that Day, is Hell - that Day, man will remember, but what good to him will be the remembrance"}, {"a": "يَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي", "e": "He will say, \"Oh, I wish I had sent ahead [some good] for my life"}, {"a": "فَيَوۡمَئِذٖ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٞ", "e": "So on that Day, none will punish [as severely] as His punishment"}, {"a": "وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٞ", "e": "And none will bind [as severely] as His binding [of the evildoers]"}, {"a": "يَـٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ", "e": "[To the righteous it will be said], \"O reassured soul"}, {"a": "ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ", "e": "Return to your Lord, well-pleased and pleasing [to Him]"}, {"a": "فَٱدۡخُلِي فِي عِبَٰدِي", "e": "And enter among My [righteous] servants"}, {"a": "وَٱدۡخُلِي جَنَّتِي", "e": "And enter My Paradise"}]}, {"n": 90, "ar": "البلد", "en": "Al-Balad", "meaning": "The City", "ayat": [{"a": "لَآ أُقۡسِمُ بِهَٰذَا ٱلۡبَلَدِ", "e": "I swear by this city, Makkah"}, {"a": "وَأَنتَ حِلُّۢ بِهَٰذَا ٱلۡبَلَدِ", "e": "And you, [O Muhammad], are free of restriction in this city"}, {"a": "وَوَالِدٖ وَمَا وَلَدَ", "e": "And [by] the father and that which was born [of him]"}, {"a": "لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ", "e": "We have certainly created man into hardship"}, {"a": "أَيَحۡسَبُ أَن لَّن يَقۡدِرَ عَلَيۡهِ أَحَدٞ", "e": "Does he think that never will anyone overcome him"}, {"a": "يَقُولُ أَهۡلَكۡتُ مَالٗا لُّبَدًا", "e": "He says, \"I have spent wealth in abundance"}, {"a": "أَيَحۡسَبُ أَن لَّمۡ يَرَهُۥٓ أَحَدٌ", "e": "Does he think that no one has seen him"}, {"a": "أَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ", "e": "Have We not made for him two eyes"}, {"a": "وَلِسَانٗا وَشَفَتَيۡنِ", "e": "And a tongue and two lips"}, {"a": "وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ", "e": "And have shown him the two ways"}, {"a": "فَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ", "e": "But he has not broken through the difficult pass"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ", "e": "And what can make you know what is [breaking through] the difficult pass"}, {"a": "فَكُّ رَقَبَةٍ", "e": "It is the freeing of a slave"}, {"a": "أَوۡ إِطۡعَٰمٞ فِي يَوۡمٖ ذِي مَسۡغَبَةٖ", "e": "Or feeding on a day of severe hunger"}, {"a": "يَتِيمٗا ذَا مَقۡرَبَةٍ", "e": "An orphan of near relationship"}, {"a": "أَوۡ مِسۡكِينٗا ذَا مَتۡرَبَةٖ", "e": "Or a needy person in misery"}, {"a": "ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُواْ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ وَتَوَاصَوۡاْ بِٱلۡمَرۡحَمَةِ", "e": "And then being among those who believed and advised one another to patience and advised one another to compassion"}, {"a": "أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡمَيۡمَنَةِ", "e": "Those are the companions of the right"}, {"a": "وَٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا هُمۡ أَصۡحَٰبُ ٱلۡمَشۡـَٔمَةِ", "e": "But they who disbelieved in Our signs - those are the companions of the left"}, {"a": "عَلَيۡهِمۡ نَارٞ مُّؤۡصَدَةُۢ", "e": "Over them will be fire closed in"}]}, {"n": 91, "ar": "الشمس", "en": "Ash-Shams", "meaning": "The Sun", "ayat": [{"a": "وَٱلشَّمۡسِ وَضُحَىٰهَا", "e": "By the sun and its brightness"}, {"a": "وَٱلۡقَمَرِ إِذَا تَلَىٰهَا", "e": "And [by] the moon when it follows it"}, {"a": "وَٱلنَّهَارِ إِذَا جَلَّىٰهَا", "e": "And [by] the day when it displays it"}, {"a": "وَٱلَّيۡلِ إِذَا يَغۡشَىٰهَا", "e": "And [by] the night when it covers it"}, {"a": "وَٱلسَّمَآءِ وَمَا بَنَىٰهَا", "e": "And [by] the sky and He who constructed it"}, {"a": "وَٱلۡأَرۡضِ وَمَا طَحَىٰهَا", "e": "And [by] the earth and He who spread it"}, {"a": "وَنَفۡسٖ وَمَا سَوَّىٰهَا", "e": "And [by] the soul and He who proportioned it"}, {"a": "فَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا", "e": "And inspired it [with discernment of] its wickedness and its righteousness"}, {"a": "قَدۡ أَفۡلَحَ مَن زَكَّىٰهَا", "e": "He has succeeded who purifies it"}, {"a": "وَقَدۡ خَابَ مَن دَسَّىٰهَا", "e": "And he has failed who instills it [with corruption]"}, {"a": "كَذَّبَتۡ ثَمُودُ بِطَغۡوَىٰهَآ", "e": "Thamud denied [their prophet] by reason of their transgression"}, {"a": "إِذِ ٱنۢبَعَثَ أَشۡقَىٰهَا", "e": "When the most wretched of them was sent forth"}, {"a": "فَقَالَ لَهُمۡ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقۡيَٰهَا", "e": "And the messenger of Allah [Salih] said to them, \"[Do not harm] the she-camel of Allah or [prevent her from] her drink"}, {"a": "فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمۡدَمَ عَلَيۡهِمۡ رَبُّهُم بِذَنۢبِهِمۡ فَسَوَّىٰهَا", "e": "But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them]"}, {"a": "وَلَا يَخَافُ عُقۡبَٰهَا", "e": "And He does not fear the consequence thereof"}]}, {"n": 92, "ar": "الليل", "en": "Al-Layl", "meaning": "The Night", "ayat": [{"a": "وَٱلَّيۡلِ إِذَا يَغۡشَىٰ", "e": "By the night when it covers"}, {"a": "وَٱلنَّهَارِ إِذَا تَجَلَّىٰ", "e": "And [by] the day when it appears"}, {"a": "وَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ", "e": "And [by] He who created the male and female"}, {"a": "إِنَّ سَعۡيَكُمۡ لَشَتَّىٰ", "e": "Indeed, your efforts are diverse"}, {"a": "فَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ", "e": "As for he who gives and fears Allah"}, {"a": "وَصَدَّقَ بِٱلۡحُسۡنَىٰ", "e": "And believes in the best [reward]"}, {"a": "فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ", "e": "We will ease him toward ease"}, {"a": "وَأَمَّا مَنۢ بَخِلَ وَٱسۡتَغۡنَىٰ", "e": "But as for he who withholds and considers himself free of need"}, {"a": "وَكَذَّبَ بِٱلۡحُسۡنَىٰ", "e": "And denies the best [reward]"}, {"a": "فَسَنُيَسِّرُهُۥ لِلۡعُسۡرَىٰ", "e": "We will ease him toward difficulty"}, {"a": "وَمَا يُغۡنِي عَنۡهُ مَالُهُۥٓ إِذَا تَرَدَّىٰٓ", "e": "And what will his wealth avail him when he falls"}, {"a": "إِنَّ عَلَيۡنَا لَلۡهُدَىٰ", "e": "Indeed, [incumbent] upon Us is guidance"}, {"a": "وَإِنَّ لَنَا لَلۡأٓخِرَةَ وَٱلۡأُولَىٰ", "e": "And indeed, to Us belongs the Hereafter and the first [life]"}, {"a": "فَأَنذَرۡتُكُمۡ نَارٗا تَلَظَّىٰ", "e": "So I have warned you of a Fire which is blazing"}, {"a": "لَا يَصۡلَىٰهَآ إِلَّا ٱلۡأَشۡقَى", "e": "None will [enter to] burn therein except the most wretched one"}, {"a": "ٱلَّذِي كَذَّبَ وَتَوَلَّىٰ", "e": "Who had denied and turned away"}, {"a": "وَسَيُجَنَّبُهَا ٱلۡأَتۡقَى", "e": "But the righteous one will avoid it"}, {"a": "ٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ", "e": "[He] who gives [from] his wealth to purify himself"}, {"a": "وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ", "e": "And not [giving] for anyone who has [done him] a favor to be rewarded"}, {"a": "إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ", "e": "But only seeking the countenance of his Lord, Most High"}, {"a": "وَلَسَوۡفَ يَرۡضَىٰ", "e": "And he is going to be satisfied"}]}, {"n": 93, "ar": "الضحى", "en": "Ad-Duhaa", "meaning": "The Morning Hours", "ayat": [{"a": "وَٱلضُّحَىٰ", "e": "By the morning brightness"}, {"a": "وَٱلَّيۡلِ إِذَا سَجَىٰ", "e": "And [by] the night when it covers with darkness"}, {"a": "مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ", "e": "Your Lord has not taken leave of you, [O Muhammad], nor has He detested [you]"}, {"a": "وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ", "e": "And the Hereafter is better for you than the first [life]"}, {"a": "وَلَسَوۡفَ يُعۡطِيكَ رَبُّكَ فَتَرۡضَىٰٓ", "e": "And your Lord is going to give you, and you will be satisfied"}, {"a": "أَلَمۡ يَجِدۡكَ يَتِيمٗا فَـَٔاوَىٰ", "e": "Did He not find you an orphan and give [you] refuge"}, {"a": "وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ", "e": "And He found you lost and guided [you]"}, {"a": "وَوَجَدَكَ عَآئِلٗا فَأَغۡنَىٰ", "e": "And He found you poor and made [you] self-sufficient"}, {"a": "فَأَمَّا ٱلۡيَتِيمَ فَلَا تَقۡهَرۡ", "e": "So as for the orphan, do not oppress [him]"}, {"a": "وَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ", "e": "And as for the petitioner, do not repel [him]"}, {"a": "وَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ", "e": "But as for the favor of your Lord, report [it]"}]}, {"n": 94, "ar": "الشرح", "en": "Ash-Sharh", "meaning": "The Relief", "ayat": [{"a": "أَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ", "e": "Did We not expand for you, [O Muhammad], your breast"}, {"a": "وَوَضَعۡنَا عَنكَ وِزۡرَكَ", "e": "And We removed from you your burden"}, {"a": "ٱلَّذِيٓ أَنقَضَ ظَهۡرَكَ", "e": "Which had weighed upon your back"}, {"a": "وَرَفَعۡنَا لَكَ ذِكۡرَكَ", "e": "And raised high for you your repute"}, {"a": "فَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا", "e": "For indeed, with hardship [will be] ease"}, {"a": "إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا", "e": "Indeed, with hardship [will be] ease"}, {"a": "فَإِذَا فَرَغۡتَ فَٱنصَبۡ", "e": "So when you have finished [your duties], then stand up [for worship]"}, {"a": "وَإِلَىٰ رَبِّكَ فَٱرۡغَب", "e": "And to your Lord direct [your] longing"}]}, {"n": 95, "ar": "التين", "en": "At-Tin", "meaning": "The Fig", "ayat": [{"a": "وَٱلتِّينِ وَٱلزَّيۡتُونِ", "e": "By the fig and the olive"}, {"a": "وَطُورِ سِينِينَ", "e": "And [by] Mount Sinai"}, {"a": "وَهَٰذَا ٱلۡبَلَدِ ٱلۡأَمِينِ", "e": "And [by] this secure city [Makkah]"}, {"a": "لَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ", "e": "We have certainly created man in the best of stature"}, {"a": "ثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ", "e": "Then We return him to the lowest of the low"}, {"a": "إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَلَهُمۡ أَجۡرٌ غَيۡرُ مَمۡنُونٖ", "e": "Except for those who believe and do righteous deeds, for they will have a reward uninterrupted"}, {"a": "فَمَا يُكَذِّبُكَ بَعۡدُ بِٱلدِّينِ", "e": "So what yet causes you to deny the Recompense"}, {"a": "أَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ", "e": "Is not Allah the most just of judges"}]}, {"n": 96, "ar": "العلق", "en": "Al-'Alaq", "meaning": "The Clot", "ayat": [{"a": "ٱقۡرَأۡ بِٱسۡمِ رَبِّكَ ٱلَّذِي خَلَقَ", "e": "Recite in the name of your Lord who created"}, {"a": "خَلَقَ ٱلۡإِنسَٰنَ مِنۡ عَلَقٍ", "e": "Created man from a clinging substance"}, {"a": "ٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ", "e": "Recite, and your Lord is the most Generous"}, {"a": "ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ", "e": "Who taught by the pen"}, {"a": "عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ", "e": "Taught man that which he knew not"}, {"a": "كَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ", "e": "No! [But] indeed, man transgresses"}, {"a": "أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ", "e": "Because he sees himself self-sufficient"}, {"a": "إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ", "e": "Indeed, to your Lord is the return"}, {"a": "أَرَءَيۡتَ ٱلَّذِي يَنۡهَىٰ", "e": "Have you seen the one who forbids"}, {"a": "عَبۡدًا إِذَا صَلَّىٰٓ", "e": "A servant when he prays"}, {"a": "أَرَءَيۡتَ إِن كَانَ عَلَى ٱلۡهُدَىٰٓ", "e": "Have you seen if he is upon guidance"}, {"a": "أَوۡ أَمَرَ بِٱلتَّقۡوَىٰٓ", "e": "Or enjoins righteousness"}, {"a": "أَرَءَيۡتَ إِن كَذَّبَ وَتَوَلَّىٰٓ", "e": "Have you seen if he denies and turns away"}, {"a": "أَلَمۡ يَعۡلَم بِأَنَّ ٱللَّهَ يَرَىٰ", "e": "Does he not know that Allah sees"}, {"a": "كَلَّا لَئِن لَّمۡ يَنتَهِ لَنَسۡفَعَۢا بِٱلنَّاصِيَةِ", "e": "No! If he does not desist, We will surely drag him by the forelock"}, {"a": "نَاصِيَةٖ كَٰذِبَةٍ خَاطِئَةٖ", "e": "A lying, sinning forelock"}, {"a": "فَلۡيَدۡعُ نَادِيَهُۥ", "e": "Then let him call his associates"}, {"a": "سَنَدۡعُ ٱلزَّبَانِيَةَ", "e": "We will call the angels of Hell"}, {"a": "كَلَّا لَا تُطِعۡهُ وَٱسۡجُدۡۤ وَٱقۡتَرِب۩", "e": "No! Do not obey him. But prostrate and draw near [to Allah]"}]}, {"n": 97, "ar": "القدر", "en": "Al-Qadr", "meaning": "The Power", "ayat": [{"a": "إِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ", "e": "Indeed, We sent the Qur'an down during the Night of Decree"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا لَيۡلَةُ ٱلۡقَدۡرِ", "e": "And what can make you know what is the Night of Decree"}, {"a": "لَيۡلَةُ ٱلۡقَدۡرِ خَيۡرٞ مِّنۡ أَلۡفِ شَهۡرٖ", "e": "The Night of Decree is better than a thousand months"}, {"a": "تَنَزَّلُ ٱلۡمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذۡنِ رَبِّهِم مِّن كُلِّ أَمۡرٖ", "e": "The angels and the Spirit descend therein by permission of their Lord for every matter"}, {"a": "سَلَٰمٌ هِيَ حَتَّىٰ مَطۡلَعِ ٱلۡفَجۡرِ", "e": "Peace it is until the emergence of dawn"}]}, {"n": 98, "ar": "البينة", "en": "Al-Bayyinah", "meaning": "The Clear Proof", "ayat": [{"a": "لَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ", "e": "Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence"}, {"a": "رَسُولٞ مِّنَ ٱللَّهِ يَتۡلُواْ صُحُفٗا مُّطَهَّرَةٗ", "e": "A Messenger from Allah, reciting purified scriptures"}, {"a": "فِيهَا كُتُبٞ قَيِّمَةٞ", "e": "Within which are correct writings"}, {"a": "وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ", "e": "Nor did those who were given the Scripture become divided until after there had come to them clear evidence"}, {"a": "وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ", "e": "And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion"}, {"a": "إِنَّ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ فِي نَارِ جَهَنَّمَ خَٰلِدِينَ فِيهَآۚ أُوْلَـٰٓئِكَ هُمۡ شَرُّ ٱلۡبَرِيَّةِ", "e": "Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures"}, {"a": "إِنَّ ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ أُوْلَـٰٓئِكَ هُمۡ خَيۡرُ ٱلۡبَرِيَّةِ", "e": "Indeed, they who have believed and done righteous deeds - those are the best of creatures"}, {"a": "جَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّـٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ", "e": "Their reward with Allah will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allah being pleased with them and they with Him. That is for whoever has feared his Lord"}]}, {"n": 99, "ar": "الزلزلة", "en": "Az-Zalzalah", "meaning": "The Earthquake", "ayat": [{"a": "إِذَا زُلۡزِلَتِ ٱلۡأَرۡضُ زِلۡزَالَهَا", "e": "When the earth is shaken with its [final] earthquake"}, {"a": "وَأَخۡرَجَتِ ٱلۡأَرۡضُ أَثۡقَالَهَا", "e": "And the earth discharges its burdens"}, {"a": "وَقَالَ ٱلۡإِنسَٰنُ مَا لَهَا", "e": "And man says, \"What is [wrong] with it"}, {"a": "يَوۡمَئِذٖ تُحَدِّثُ أَخۡبَارَهَا", "e": "That Day, it will report its news"}, {"a": "بِأَنَّ رَبَّكَ أَوۡحَىٰ لَهَا", "e": "Because your Lord has commanded it"}, {"a": "يَوۡمَئِذٖ يَصۡدُرُ ٱلنَّاسُ أَشۡتَاتٗا لِّيُرَوۡاْ أَعۡمَٰلَهُمۡ", "e": "That Day, the people will depart separated [into categories] to be shown [the result of] their deeds"}, {"a": "فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ", "e": "So whoever does an atom's weight of good will see it"}, {"a": "وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ", "e": "And whoever does an atom's weight of evil will see it"}]}, {"n": 100, "ar": "العاديات", "en": "Al-'Adiyat", "meaning": "The Courser", "ayat": [{"a": "وَٱلۡعَٰدِيَٰتِ ضَبۡحٗا", "e": "By the racers, panting"}, {"a": "فَٱلۡمُورِيَٰتِ قَدۡحٗا", "e": "And the producers of sparks [when] striking"}, {"a": "فَٱلۡمُغِيرَٰتِ صُبۡحٗا", "e": "And the chargers at dawn"}, {"a": "فَأَثَرۡنَ بِهِۦ نَقۡعٗا", "e": "Stirring up thereby [clouds of] dust"}, {"a": "فَوَسَطۡنَ بِهِۦ جَمۡعًا", "e": "Arriving thereby in the center collectively"}, {"a": "إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ", "e": "Indeed mankind, to his Lord, is ungrateful"}, {"a": "وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٞ", "e": "And indeed, he is to that a witness"}, {"a": "وَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ", "e": "And indeed he is, in love of wealth, intense"}, {"a": "۞أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ", "e": "But does he not know that when the contents of the graves are scattered"}, {"a": "وَحُصِّلَ مَا فِي ٱلصُّدُورِ", "e": "And that within the breasts is obtained"}, {"a": "إِنَّ رَبَّهُم بِهِمۡ يَوۡمَئِذٖ لَّخَبِيرُۢ", "e": "Indeed, their Lord with them, that Day, is [fully] Acquainted"}]}, {"n": 101, "ar": "القارعة", "en": "Al-Qari'ah", "meaning": "The Calamity", "ayat": [{"a": "ٱلۡقَارِعَةُ", "e": "The Striking Calamity"}, {"a": "مَا ٱلۡقَارِعَةُ", "e": "What is the Striking Calamity"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا ٱلۡقَارِعَةُ", "e": "And what can make you know what is the Striking Calamity"}, {"a": "يَوۡمَ يَكُونُ ٱلنَّاسُ كَٱلۡفَرَاشِ ٱلۡمَبۡثُوثِ", "e": "It is the Day when people will be like moths, dispersed"}, {"a": "وَتَكُونُ ٱلۡجِبَالُ كَٱلۡعِهۡنِ ٱلۡمَنفُوشِ", "e": "And the mountains will be like wool, fluffed up"}, {"a": "فَأَمَّا مَن ثَقُلَتۡ مَوَٰزِينُهُۥ", "e": "Then as for one whose scales are heavy [with good deeds]"}, {"a": "فَهُوَ فِي عِيشَةٖ رَّاضِيَةٖ", "e": "He will be in a pleasant life"}, {"a": "وَأَمَّا مَنۡ خَفَّتۡ مَوَٰزِينُهُۥ", "e": "But as for one whose scales are light"}, {"a": "فَأُمُّهُۥ هَاوِيَةٞ", "e": "His refuge will be an abyss"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا هِيَهۡ", "e": "And what can make you know what that is"}, {"a": "نَارٌ حَامِيَةُۢ", "e": "It is a Fire, intensely hot"}]}, {"n": 102, "ar": "التكاثر", "en": "At-Takathur", "meaning": "The Rivalry in world increase", "ayat": [{"a": "أَلۡهَىٰكُمُ ٱلتَّكَاثُرُ", "e": "Competition in [worldly] increase diverts you"}, {"a": "حَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ", "e": "Until you visit the graveyards"}, {"a": "كَلَّا سَوۡفَ تَعۡلَمُونَ", "e": "No! You are going to know"}, {"a": "ثُمَّ كَلَّا سَوۡفَ تَعۡلَمُونَ", "e": "Then no! You are going to know"}, {"a": "كَلَّا لَوۡ تَعۡلَمُونَ عِلۡمَ ٱلۡيَقِينِ", "e": "No! If you only knew with knowledge of certainty"}, {"a": "لَتَرَوُنَّ ٱلۡجَحِيمَ", "e": "You will surely see the Hellfire"}, {"a": "ثُمَّ لَتَرَوُنَّهَا عَيۡنَ ٱلۡيَقِينِ", "e": "Then you will surely see it with the eye of certainty"}, {"a": "ثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ", "e": "Then you will surely be asked that Day about pleasure"}]}, {"n": 103, "ar": "العصر", "en": "Al-'Asr", "meaning": "The Declining Day", "ayat": [{"a": "وَٱلۡعَصۡرِ", "e": "By time"}, {"a": "إِنَّ ٱلۡإِنسَٰنَ لَفِي خُسۡرٍ", "e": "Indeed, mankind is in loss"}, {"a": "إِلَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ وَتَوَاصَوۡاْ بِٱلۡحَقِّ وَتَوَاصَوۡاْ بِٱلصَّبۡرِ", "e": "Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience"}]}, {"n": 104, "ar": "الهمزة", "en": "Al-Humazah", "meaning": "The Traducer", "ayat": [{"a": "وَيۡلٞ لِّكُلِّ هُمَزَةٖ لُّمَزَةٍ", "e": "Woe to every scorner and mocker"}, {"a": "ٱلَّذِي جَمَعَ مَالٗا وَعَدَّدَهُۥ", "e": "Who collects wealth and [continuously] counts it"}, {"a": "يَحۡسَبُ أَنَّ مَالَهُۥٓ أَخۡلَدَهُۥ", "e": "He thinks that his wealth will make him immortal"}, {"a": "كَلَّاۖ لَيُنۢبَذَنَّ فِي ٱلۡحُطَمَةِ", "e": "No! He will surely be thrown into the Crusher"}, {"a": "وَمَآ أَدۡرَىٰكَ مَا ٱلۡحُطَمَةُ", "e": "And what can make you know what is the Crusher"}, {"a": "نَارُ ٱللَّهِ ٱلۡمُوقَدَةُ", "e": "It is the fire of Allah, [eternally] fueled"}, {"a": "ٱلَّتِي تَطَّلِعُ عَلَى ٱلۡأَفۡـِٔدَةِ", "e": "Which mounts directed at the hearts"}, {"a": "إِنَّهَا عَلَيۡهِم مُّؤۡصَدَةٞ", "e": "Indeed, Hellfire will be closed down upon them"}, {"a": "فِي عَمَدٖ مُّمَدَّدَةِۭ", "e": "In extended columns"}]}, {"n": 105, "ar": "الفيل", "en": "Al-Fil", "meaning": "The Elephant", "ayat": [{"a": "أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ", "e": "Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant"}, {"a": "أَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلٖ", "e": "Did He not make their plan into misguidance"}, {"a": "وَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ", "e": "And He sent against them birds in flocks"}, {"a": "تَرۡمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ", "e": "Striking them with stones of hard clay"}, {"a": "فَجَعَلَهُمۡ كَعَصۡفٖ مَّأۡكُولِۭ", "e": "And He made them like eaten straw"}]}, {"n": 106, "ar": "قريش", "en": "Quraysh", "meaning": "Quraysh", "ayat": [{"a": "لِإِيلَٰفِ قُرَيۡشٍ", "e": "For the accustomed security of the Quraysh"}, {"a": "إِۦلَٰفِهِمۡ رِحۡلَةَ ٱلشِّتَآءِ وَٱلصَّيۡفِ", "e": "Their accustomed security [in] the caravan of winter and summer"}, {"a": "فَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ", "e": "Let them worship the Lord of this House"}, {"a": "ٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعٖ وَءَامَنَهُم مِّنۡ خَوۡفِۭ", "e": "Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear"}]}, {"n": 107, "ar": "الماعون", "en": "Al-Ma'un", "meaning": "The Small kindnesses", "ayat": [{"a": "أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ", "e": "Have you seen the one who denies the Recompense"}, {"a": "فَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ", "e": "For that is the one who drives away the orphan"}, {"a": "وَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ", "e": "And does not encourage the feeding of the poor"}, {"a": "فَوَيۡلٞ لِّلۡمُصَلِّينَ", "e": "So woe to those who pray"}, {"a": "ٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ", "e": "[But] who are heedless of their prayer"}, {"a": "ٱلَّذِينَ هُمۡ يُرَآءُونَ", "e": "Those who make show [of their deeds]"}, {"a": "وَيَمۡنَعُونَ ٱلۡمَاعُونَ", "e": "And withhold [simple] assistance"}]}, {"n": 108, "ar": "الكوثر", "en": "Al-Kawthar", "meaning": "The Abundance", "ayat": [{"a": "إِنَّآ أَعۡطَيۡنَٰكَ ٱلۡكَوۡثَرَ", "e": "Indeed, We have granted you, [O Muhammad], al-Kawthar"}, {"a": "فَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ", "e": "So pray to your Lord and sacrifice [to Him alone]"}, {"a": "إِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ", "e": "Indeed, your enemy is the one cut off"}]}, {"n": 109, "ar": "الكافرون", "en": "Al-Kafirun", "meaning": "The Disbelievers", "ayat": [{"a": "قُلۡ يَـٰٓأَيُّهَا ٱلۡكَٰفِرُونَ", "e": "Say, \"O disbelievers"}, {"a": "لَآ أَعۡبُدُ مَا تَعۡبُدُونَ", "e": "I do not worship what you worship"}, {"a": "وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ", "e": "Nor are you worshippers of what I worship"}, {"a": "وَلَآ أَنَا۠ عَابِدٞ مَّا عَبَدتُّمۡ", "e": "Nor will I be a worshipper of what you worship"}, {"a": "وَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ", "e": "Nor will you be worshippers of what I worship"}, {"a": "لَكُمۡ دِينُكُمۡ وَلِيَ دِينِ", "e": "For you is your religion, and for me is my religion"}]}, {"n": 110, "ar": "النصر", "en": "An-Nasr", "meaning": "The Divine Support", "ayat": [{"a": "إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ", "e": "When the victory of Allah has come and the conquest"}, {"a": "وَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا", "e": "And you see the people entering into the religion of Allah in multitudes"}, {"a": "فَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا", "e": "Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance"}]}, {"n": 111, "ar": "المسد", "en": "Al-Masad", "meaning": "The Palm Fiber", "ayat": [{"a": "تَبَّتۡ يَدَآ أَبِي لَهَبٖ وَتَبَّ", "e": "May the hands of Abu Lahab be ruined, and ruined is he"}, {"a": "مَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ", "e": "His wealth will not avail him or that which he gained"}, {"a": "سَيَصۡلَىٰ نَارٗا ذَاتَ لَهَبٖ", "e": "He will [enter to] burn in a Fire of [blazing] flame"}, {"a": "وَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ", "e": "And his wife [as well] - the carrier of firewood"}, {"a": "فِي جِيدِهَا حَبۡلٞ مِّن مَّسَدِۭ", "e": "Around her neck is a rope of [twisted] fiber"}]}, {"n": 112, "ar": "الإخلاص", "en": "Al-Ikhlas", "meaning": "The Sincerity", "ayat": [{"a": "قُلۡ هُوَ ٱللَّهُ أَحَدٌ", "e": "Say, \"He is Allah, [who is] One"}, {"a": "ٱللَّهُ ٱلصَّمَدُ", "e": "Allah, the Eternal Refuge"}, {"a": "لَمۡ يَلِدۡ وَلَمۡ يُولَدۡ", "e": "He neither begets nor is born"}, {"a": "وَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ", "e": "Nor is there to Him any equivalent"}]}, {"n": 113, "ar": "الفلق", "en": "Al-Falaq", "meaning": "The Daybreak", "ayat": [{"a": "قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ", "e": "Say, \"I seek refuge in the Lord of daybreak"}, {"a": "مِن شَرِّ مَا خَلَقَ", "e": "From the evil of that which He created"}, {"a": "وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ", "e": "And from the evil of darkness when it settles"}, {"a": "وَمِن شَرِّ ٱلنَّفَّـٰثَٰتِ فِي ٱلۡعُقَدِ", "e": "And from the evil of the blowers in knots"}, {"a": "وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ", "e": "And from the evil of an envier when he envies"}]}, {"n": 114, "ar": "الناس", "en": "An-Nas", "meaning": "Mankind", "ayat": [{"a": "قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ", "e": "Say, \"I seek refuge in the Lord of mankind"}, {"a": "مَلِكِ ٱلنَّاسِ", "e": "The Sovereign of mankind"}, {"a": "إِلَٰهِ ٱلنَّاسِ", "e": "The God of mankind"}, {"a": "مِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ", "e": "From the evil of the retreating whisperer"}, {"a": "ٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ", "e": "Who whispers [evil] into the breasts of mankind"}, {"a": "مِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ", "e": "From among the jinn and mankind"}]}];
